package com.maikal.daily;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public class CustomWidgetConfigureActivity extends Activity {
 private int widgetId=AppWidgetManager.INVALID_APPWIDGET_ID;private JSONObject plan;private LinearLayout root,preview,order;private EditText name;private Spinner sizes,appearance,types,moneyViews;private LinearLayout shortcutSettings,moneySettings;private CheckBox[] checks;private boolean rendering;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private int ink(){return MantraTheme.color(this,0xff253439);}private int muted(){return MantraTheme.color(this,0xff72756e);}
 private TextView text(String label,int size){TextView t=new TextView(this);t.setText(label);t.setTextSize(size);t.setTextColor(ink());t.setPadding(0,dp(8),0,dp(8));return t;}
 private Button button(String label,LinearLayout parent,Runnable action){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextColor(MantraTheme.color(this,0xff25704d));b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);parent.addView(b);b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle state){MantraTheme.activity(this);super.onCreate(state);setResult(RESULT_CANCELED);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);
  try{if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID&&!CustomWidgetProvider.owns(this,widgetId)){finish();return;}plan=state!=null?new JSONObject(state.getString("plan")):widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID?CustomWidgetStore.widget(this,widgetId):null;if(plan==null)plan=CustomWidgetStore.defaults();if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){plan.put("size",CustomWidgetProvider.size(this,widgetId));trimActions();}render();}catch(Exception e){error(e);finish();}}
 @Override protected void onSaveInstanceState(Bundle state){try{plan.put("name",name.getText().toString());state.putString("plan",plan.toString());}catch(Exception ignored){}super.onSaveInstanceState(state);}
 private void error(Exception e){Toast.makeText(this,e.getMessage()==null?"Could not update widget":e.getMessage(),Toast.LENGTH_LONG).show();}
 private ArrayList<String> actions(){ArrayList<String> result=new ArrayList<>();JSONArray a=plan.optJSONArray("actions");if(a!=null)for(int i=0;i<a.length();i++)result.add(a.optString(i));return result;}
 private void trimActions()throws Exception{ArrayList<String> a=actions();while(a.size()>CustomWidgetStore.capacity(plan.getString("size")))a.remove(a.size()-1);plan.put("actions",new JSONArray(a));}
 private Spinner spinner(String[] values,LinearLayout parent){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));parent.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));return s;}
 private void render()throws Exception{
  rendering=true;ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(12),dp(22),dp(32));root.setBackgroundColor(MantraTheme.color(this,0xffffffff));scroll.addView(root);scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(scroll);
  button("‹ Back",root,this::finish);root.addView(text(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID?"Custom widget":"Edit custom widget",27));
  button("Load a saved layout",root,this::loadLayout);if(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID)button("Manage home-screen widgets",root,this::manage);
  root.addView(text("Widget name",13));name=new EditText(this);name.setSingleLine(true);name.setContentDescription("Widget name");name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});name.setText(plan.optString("name"));name.setTextColor(ink());root.addView(name);
  root.addView(text("Size · columns × rows",13));sizes=spinner(Arrays.stream(CustomWidgetStore.SIZES).map(s->s.replace("x"," × ")).toArray(String[]::new),root);sizes.setContentDescription("Widget size");sizes.setSelection(Arrays.asList(CustomWidgetStore.SIZES).indexOf(plan.getString("size")));sizes.setEnabled(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID);
  TextView help=text(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID?"Your launcher controls final placement and cell dimensions. A 1 × 1 widget holds one action.":"The home-screen size stays the same. Change this widget’s actions, order and appearance below.",12);help.setTextColor(muted());root.addView(help);
  root.addView(text("Widget type",16));types=spinner(new String[]{"Shortcut buttons","Money summary"},root);types.setContentDescription("Widget type");types.setSelection("money".equals(plan.optString("type"))?1:0);
  moneySettings=new LinearLayout(this);moneySettings.setOrientation(1);root.addView(moneySettings);moneySettings.addView(text("Choose money figures",16));moneyViews=spinner(new String[]{"Today’s summary","Today’s expenses","Today’s income","Today’s savings","This month’s summary","This month’s expenses","This month’s income","This month’s savings"},moneySettings);moneyViews.setContentDescription("Money figures");moneyViews.setSelection(Arrays.asList(CustomWidgetStore.MONEY_VIEWS).indexOf(plan.getString("moneyView")));moneySettings.addView(text("Full summaries show income, expenses and savings and need at least three cells. Figures come from the diary currently open in MANTRA and refresh when the app syncs.",12));
  shortcutSettings=new LinearLayout(this);shortcutSettings.setOrientation(1);root.addView(shortcutSettings);
  shortcutSettings.addView(text("Choose buttons",16));checks=new CheckBox[4];ArrayList<String> selected=actions();for(int i=0;i<4;i++){final String action=CustomWidgetStore.ACTIONS[i];CheckBox check=new CheckBox(this);checks[i]=check;check.setText(CustomWidgetStore.LABELS[i]);check.setTextColor(ink());check.setChecked(selected.contains(action));shortcutSettings.addView(check);check.setOnCheckedChangeListener((b,on)->{if(rendering)return;try{ArrayList<String> a=actions();if(on&&!a.contains(action)){if(a.size()>=CustomWidgetStore.capacity(plan.getString("size"))){rendering=true;check.setChecked(false);rendering=false;Toast.makeText(this,"Choose up to "+CustomWidgetStore.capacity(plan.getString("size"))+" buttons for this size",Toast.LENGTH_SHORT).show();return;}a.add(action);}else if(!on)a.remove(action);plan.put("actions",new JSONArray(a));refreshPreview();}catch(Exception e){error(e);}});}
  shortcutSettings.addView(text("Button order",16));order=new LinearLayout(this);order.setOrientation(1);shortcutSettings.addView(order);
  root.addView(text("Appearance",16));String[] appearances={"Follow app theme","Light","Dark","Transparent"};appearance=spinner(appearances,root);appearance.setContentDescription("Widget appearance");appearance.setSelection(Arrays.asList(new String[]{"app","light","dark","transparent"}).indexOf(plan.getString("appearance")));
  root.addView(text("Preview",16));preview=new LinearLayout(this);preview.setOrientation(1);preview.setPadding(dp(8),dp(8),dp(8),dp(8));root.addView(preview,new LinearLayout.LayoutParams(-1,dp(220)));
  button("Save layout",root,()->{try{syncName();CustomWidgetStore.saveLayout(this,plan);Toast.makeText(this,"Layout saved on this device",Toast.LENGTH_SHORT).show();}catch(Exception e){error(e);}});
  button(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID?"Add to home screen":"Save widget",root,this::finishWidget);
  sizes.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering)return;try{plan.put("size",CustomWidgetStore.SIZES[index]);int before=actions().size();trimActions();rendering=true;for(int i=0;i<4;i++)checks[i].setChecked(actions().contains(CustomWidgetStore.ACTIONS[i]));rendering=false;if(before>actions().size())Toast.makeText(CustomWidgetConfigureActivity.this,"Kept the first "+actions().size()+" buttons to fit this size",Toast.LENGTH_SHORT).show();refreshPreview();}catch(Exception e){error(e);}}});
  appearance.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering)return;try{plan.put("appearance",new String[]{"app","light","dark","transparent"}[index]);refreshPreview();}catch(Exception e){error(e);}}});
  types.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering)return;try{plan.put("type",index==1?"money":"shortcuts");if(index==1){if("My shortcuts".equals(name.getText().toString()))name.setText("My money");plan.put("uid",NativeDiaryStore.uid(CustomWidgetConfigureActivity.this));if(CustomWidgetStore.capacity(plan.getString("size"))<3&&plan.getString("moneyView").endsWith("summary")){plan.put("moneyView","today_expense");moneyViews.setSelection(1);}}refreshPreview();}catch(Exception e){error(e);}}});
  moneyViews.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int index,long id){if(rendering)return;try{plan.put("moneyView",CustomWidgetStore.MONEY_VIEWS[index]).put("uid",NativeDiaryStore.uid(CustomWidgetConfigureActivity.this));refreshPreview();}catch(Exception e){error(e);}}});
  rendering=false;refreshPreview();
 }
 private void syncName()throws Exception{plan.put("name",name.getText().toString().trim());if("money".equals(plan.optString("type")))plan.put("uid",NativeDiaryStore.uid(this));plan=CustomWidgetStore.validate(plan);}
 private void refreshPreview()throws Exception{
  boolean money="money".equals(plan.optString("type"));shortcutSettings.setVisibility(money?View.GONE:View.VISIBLE);moneySettings.setVisibility(money?View.VISIBLE:View.GONE);
  order.removeAllViews();ArrayList<String> a=actions();for(int i=0;i<a.size();i++){final int index=i;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView label=text(CustomWidgetStore.label(a.get(i)),13);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));Button up=button("↑",row,()->move(index,-1));up.setContentDescription("Move "+CustomWidgetStore.label(a.get(i))+" up");up.setEnabled(i>0);Button down=button("↓",row,()->move(index,1));down.setContentDescription("Move "+CustomWidgetStore.label(a.get(i))+" down");down.setEnabled(i<a.size()-1);order.addView(row);}
  preview.removeAllViews();boolean dark=CustomWidgetProvider.dark(this,plan);preview.setBackgroundColor("transparent".equals(plan.optString("appearance"))?MantraTheme.color(this,0xffeae8de):dark?0xff182126:Color.WHITE);
  if(!money&&a.isEmpty()){preview.addView(text("Choose at least one button",15));return;}JSONObject snapshot=new JSONObject(plan.toString());snapshot.put("name",name.getText().toString().isEmpty()?"My shortcuts":name.getText().toString());String[] dims=plan.getString("size").split("x");int x=Integer.parseInt(dims[0]),y=Integer.parseInt(dims[1]);int maximum=getResources().getDisplayMetrics().widthPixels-dp(60);float scale=Math.min(maximum/(float)dp(x*70),dp(300)/(float)dp(y*70));int width=(int)(dp(x*70)*scale),height=(int)(dp(y*70)*scale);Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,Math.round(height/getResources().getDisplayMetrics().density));options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,Math.round(width/getResources().getDisplayMetrics().density));View example=CustomWidgetProvider.views(this,widgetId,snapshot,options).apply(this,preview);example.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);disable(example);preview.setGravity(Gravity.CENTER);preview.getLayoutParams().height=height+dp(16);preview.addView(example,new LinearLayout.LayoutParams(width,height));
 }
 private void disable(View v){v.setEnabled(false);v.setClickable(false);v.setFocusable(false);if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++)disable(group.getChildAt(i));}}
 private void move(int index,int step){try{ArrayList<String> a=actions();int next=index+step;if(next<0||next>=a.size())return;Collections.swap(a,index,next);plan.put("actions",new JSONArray(a));refreshPreview();}catch(Exception e){error(e);}}
 private void loadLayout(){JSONObject saved=CustomWidgetStore.layouts(this);ArrayList<String> ids=new ArrayList<>(),labels=new ArrayList<>();java.util.Iterator<String> keys=saved.keys();while(keys.hasNext()){String id=keys.next();JSONObject p=saved.optJSONObject(id);if(p!=null){ids.add(id);labels.add(p.optString("name")+" · "+p.optString("size"));}}if(ids.isEmpty()){Toast.makeText(this,"No saved layouts yet",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Saved layouts").setItems(labels.toArray(new String[0]),(d,index)->{try{plan=CustomWidgetStore.validate(saved.getJSONObject(ids.get(index)));if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){plan.put("size",CustomWidgetProvider.size(this,widgetId));trimActions();if("money".equals(plan.optString("type"))&&plan.getString("moneyView").endsWith("summary")&&CustomWidgetStore.capacity(plan.getString("size"))<3)plan.put("moneyView",plan.getString("moneyView").replace("summary","expense"));}if("money".equals(plan.optString("type")))plan.put("uid",NativeDiaryStore.uid(this));render();}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show();}
 private void manage(){AppWidgetManager m=AppWidgetManager.getInstance(this);ArrayList<Integer> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(Class<?> type:CustomWidgetProvider.TYPES)for(int id:m.getAppWidgetIds(new ComponentName(this,type))){JSONObject p=CustomWidgetStore.widget(this,id);ids.add(id);labels.add((p==null?"Set up widget":p.optString("name"))+" · "+CustomWidgetProvider.size(this,id));}if(ids.isEmpty()){Toast.makeText(this,"No custom widgets on the home screen yet",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Your custom widgets").setItems(labels.toArray(new String[0]),(d,index)->startActivity(new Intent(this,CustomWidgetConfigureActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,ids.get(index)))).setNegativeButton("Cancel",null).show();}
 private void finishWidget(){try{syncName();if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){CustomWidgetStore.configure(this,widgetId,plan);CustomWidgetProvider.update(this,widgetId);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();return;}
   AppWidgetManager m=AppWidgetManager.getInstance(this);String layout=CustomWidgetStore.saveLayout(this,plan);if(!m.isRequestPinAppWidgetSupported()){new AlertDialog.Builder(this).setTitle("Layout saved").setMessage("Long-press your home screen, open Widgets → MANTRA, select Custom widget in this size, then load this saved layout.").setPositiveButton("OK",null).show();return;}
   Intent callback=new Intent(this,CustomWidgetPinnedReceiver.class).setData(Uri.parse("mantra-widget://pinned/"+layout)).putExtra("layoutId",layout);PendingIntent done=PendingIntent.getBroadcast(this,0,callback,PendingIntent.FLAG_UPDATE_CURRENT|(android.os.Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0));Bundle extras=new Bundle();extras.putParcelable(AppWidgetManager.EXTRA_APPWIDGET_PREVIEW,CustomWidgetProvider.views(this,0,plan,new Bundle()));boolean requested=m.requestPinAppWidget(CustomWidgetProvider.component(this,plan.getString("size")),extras,done);if(requested)Toast.makeText(this,"Confirm placement on your home screen. This layout is saved if you cancel.",Toast.LENGTH_LONG).show();else Toast.makeText(this,"Your launcher could not add the widget. Use its widget picker and load the saved layout.",Toast.LENGTH_LONG).show();
  }catch(Exception e){error(e);}}
}
